import{_ as e,o as s,c as t,a2 as n}from"./chunks/framework.BvlN9b-o.js";const u=JSON.parse('{"title":"项目结构","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/architecture/project-structure","contentType":"concept","prev":{"text":"快速开始","link":"/getting-started/quickstart"},"next":{"text":"新增业务模块","link":"/guides/new-module"}},"headers":[],"relativePath":"architecture/project-structure.md","filePath":"architecture/project-structure.md"}'),p={name:"architecture/project-structure.md"};function r(c,a,o,d,i,l){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h1><p>自己的业务放在 Rust Application 模块中，通过 API 和 Worker 入口接入。先找到这些位置，再开始写第一条接口。</p><h2 id="后端目录地图" tabindex="-1">后端目录地图 <a class="header-anchor" href="#后端目录地图" aria-label="Permalink to &quot;后端目录地图&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apps/</span></span>
<span class="line"><span>  api/src/main.rs        HTTP 进程：配置、连接池、启动与停止</span></span>
<span class="line"><span>  api/src/lib.rs         API 组装：Router、OpenAPI、模块选项</span></span>
<span class="line"><span>  worker/src/main.rs     后台进程：Handler、维护任务与健康检查</span></span>
<span class="line"><span>crates/</span></span>
<span class="line"><span>  app/src/http.rs        RequestId、公开错误、输入提取器</span></span>
<span class="line"><span>  app/src/modules/      SaaS Core 与具体业务模块</span></span>
<span class="line"><span>  platform/src/         数据库、存储、邮件、Redis 与观测适配</span></span>
<span class="line"><span>migrations/             显式执行的 SQL 迁移</span></span>
<span class="line"><span>apps/api/tests/         组合应用的公开 HTTP 行为</span></span>
<span class="line"><span>crates/app/tests/       Core 的公开能力与纯业务规则</span></span>
<span class="line"><span>examples/               可替换业务的所有权与教学源码</span></span>
<span class="line"><span>packages/contracts/     Rust OpenAPI 生成的协议</span></span>
<span class="line"><span>packages/sdk/           生成客户端与少量 transport 配置</span></span></code></pre></div><p>完整客户端、部署和文档布局见 <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/README.zh-CN.md" target="_blank" rel="noreferrer">README</a>。这里聚焦开发后端会修改的位置。</p><h2 id="一个新功能放在哪里" tabindex="-1">一个新功能放在哪里 <a class="header-anchor" href="#一个新功能放在哪里" aria-label="Permalink to &quot;一个新功能放在哪里&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目标</th><th>位置</th><th>负责的内容</th></tr></thead><tbody><tr><td>新增工单业务</td><td><code>crates/app/src/modules/tickets/</code></td><td>实体、业务规则、用例、HTTP 与公开接口</td></tr><tr><td>声明模块</td><td><code>crates/app/src/modules/mod.rs</code></td><td>Rust 模块入口</td></tr><tr><td>增加表</td><td><code>migrations/</code> 与模块 <code>module.json</code></td><td>SQL 迁移与表所有权</td></tr><tr><td>接入 API</td><td><code>apps/api/src/lib.rs</code></td><td>合并业务 Router、OpenAPI 与可用 scopes</td></tr><tr><td>增加耗时处理</td><td><code>apps/worker/src/main.rs</code></td><td>注册业务 Handler 与维护任务</td></tr><tr><td>验证公开行为</td><td><code>apps/api/tests/</code></td><td>请求、响应、权限、持久化与失败结果</td></tr><tr><td>连接客户端</td><td><code>packages/contracts/</code>、<code>packages/sdk/</code></td><td>由 Rust 合同生成协议与方法</td></tr></tbody></table><p><code>tickets</code> 是学习者将新增的业务。默认模板已经注册知识库；新增业务可以与它共用 SaaS Core。</p><h2 id="请求经过哪些职责" tabindex="-1">请求经过哪些职责 <a class="header-anchor" href="#请求经过哪些职责" aria-label="Permalink to &quot;请求经过哪些职责&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP 请求</span></span>
<span class="line"><span>  → 应用组装的 Router</span></span>
<span class="line"><span>  → 模块 HTTP 边界：DTO、提取器、错误映射</span></span>
<span class="line"><span>  → Application：授权、事务、公共能力协作</span></span>
<span class="line"><span>  → Domain 规则与 SQLx 查询</span></span>
<span class="line"><span>  → PostgreSQL / Platform 适配器</span></span></code></pre></div><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/crates/app/src/lib.rs" target="_blank" rel="noreferrer">Core 组装器</a>接收额外 Router 和组合 OpenAPI。<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/apps/api/src/lib.rs" target="_blank" rel="noreferrer">API 入口</a>决定实际注册的业务。Core 与 Platform 不 import 具体业务。</p><p>小模块可以先在 <code>mod.rs</code> 内完成一个用例。规则与编排变复杂时，再像现有参考业务一样拆出 <code>domain.rs</code> 和 <code>application.rs</code>：Domain 保持纯规则，Application 持有事务，HTTP 边界负责协议。</p><h2 id="框架能力和业务的归属" tabindex="-1">框架能力和业务的归属 <a class="header-anchor" href="#框架能力和业务的归属" aria-label="Permalink to &quot;框架能力和业务的归属&quot;">​</a></h2><p>SaaS Core 提供身份、成员、会话、审计、幂等、任务、文件、通知、邮件和通用 HTTP 能力。你的模块定义自己的资源与规则，并在自己的事务中调用公开接口。</p><p>例如审计的 <code>append</code> 接收调用者的连接，业务写入和审计一起提交。对象上传和邮件投递是数据库之外的 I/O，需要明确的发布、任务与失败恢复流程。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boundaries:check</span></span></code></pre></div><p>这项检查验证包依赖、模块表归属、纯 Domain 的基础设施导入和示例清单；真实 HTTP 测试补充权限与事务行为。进一步说明见 <a href="./boundaries">Core 与业务边界</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>按<a href="./../guides/new-module">新增业务模块</a>创建一个完整 Rust 文件，注册 Router 与 OpenAPI，然后用 HTTP 请求验证结果。</p><hr><p>源码版本：<code>e2df5399c4b9</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/e2df5399c4b9da982ab8e043578a50a75c40f885/docs/architecture/project-structure.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,21)])])}const b=e(p,[["render",r]]);export{u as __pageData,b as default};
